# Beantragung, Vertragszeitraum, Ausstieg, Stallskizze (Kapitel 3.1, 6.3.2, 7, 8 Informationsblatt; 1.7, 1.10 SRL).
package oepul.o6_21

import rego.v1

applications := object.get(o6_21_input, "applications", [])

supplement_id := "festmistkompostierung"

# O6_21-APP-001: Beantragung im Maßnahmenantrag bis 31. Dezember vor Vertragsbeginn.
application_deadline_ns(first_year) := date_ns(sprintf("%d-%s", [first_year - 1, params.application_deadline_month_day]))

application_timely(app) if date_ns(app.submitted_date) <= application_deadline_ns(app.first_year)

# O6_21-APP-005: verspätete Wiederbeantragung nach Erlöschen - Korrektur plus schriftliches Ersuchen.
application_timely(app) if {
	app.late_reapplication_after_lapse == true
	app.written_request_to_ama == true
}

# O6_21-APP-002 / O6_21-GEN-007: letzter Einstieg Kategorien 2027, Zuschlag 2028.
last_entry_year(item) := params.last_entry_year_supplement if item == supplement_id

else := params.last_entry_year_categories

application_violations contains {"rule_id": "O6_21-APP-001", "item": app.item, "reason": "Maßnahmenantrag nicht bis 31. Dezember vor Vertragsbeginn gestellt"} if {
	some app in applications
	not application_timely(app)
}

application_violations contains {"rule_id": "O6_21-APP-002", "item": app.item, "reason": "Einstieg nach dem letzten möglichen Förderjahr"} if {
	some app in applications
	app.first_year > last_entry_year(app.item)
}

application_violations contains {"rule_id": "O6_21-CAT-001", "item": c, "reason": "keine zulässige Tierkategorie der Maßnahme"} if {
	some c in unknown_applied_categories
}

application_violations contains {"rule_id": "O6_21-ACC-003", "item": c, "reason": "Betrieb mit Milchanlieferung von der Kategorie weibliche Rinder ab ½ bis unter 2 Jahre ausgeschlossen"} if {
	some c in category_excluded
	categories_by_id[c].excluded_for_milk_delivering_farms == true
}

# Gültiger Vertrag für ein Element (Kategorie oder Zuschlag) im Förderjahr.
contract_valid(item) if {
	some app in applications
	app.item == item
	application_timely(app)
	app.first_year <= measure_year
	app.first_year <= last_entry_year(item)
	not exited_during_year(item)
	not measure_exited_during_year
}

# O6_21-APP-006: Zuschlag Festmistkompostierung erfordert Maßnahmenantrag.
application_violations contains {"rule_id": "O6_21-APP-006", "item": supplement_id, "reason": "Zuschlag ohne gültigen Maßnahmenantrag"} if {
	composting_supplement_applied
	not contract_valid(supplement_id)
}

application_violations contains {"rule_id": "O6_21-APP-001", "item": c, "reason": "Kategorie ohne gültigen Vertrag für das Förderjahr"} if {
	some c in applied_categories
	not c in unknown_applied_categories
	not contract_valid(c)
}

# ---------------------------------------------------------------------------
# Ausstieg (O6_21-EXIT-001 bis O6_21-EXIT-005)
# ---------------------------------------------------------------------------

exits := object.get(o6_21_input, "exits", [])

exit_in_year(e) if {
	d := date_ns(e.date)
	d >= year_start_ns
	d < year_end_excl_ns
}

# O6_21-EXIT-003: Abmeldung im Zeitraum 1.1.-31.12. - Maßnahme (bzw. Element) im Förderjahr nicht mehr gültig.
measure_exited_during_year if {
	some e in exits
	e.item == "measure"
	exit_in_year(e)
}

exited_during_year(item) if {
	some e in exits
	e.item == item
	exit_in_year(e)
}

# O6_21-EXIT-005: Ausstieg nur bis zur Ankündigung/Durchführung einer Vor-Ort-Kontrolle bzw. Mitteilung einer Verwaltungskontrolle.
application_violations contains {"rule_id": "O6_21-EXIT-005", "item": e.item, "reason": "Ausstieg nach Ankündigung/Durchführung einer Vor-Ort-Kontrolle oder Mitteilung des Verwaltungskontrollergebnisses"} if {
	some e in exits
	e.after_control_announcement_or_result == true
}

# ---------------------------------------------------------------------------
# Stallskizze und Belegungsplan (O6_21-SKETCH-001 / O6_21-SKETCH-004)
# ---------------------------------------------------------------------------

default stall_sketch_required := false

stall_sketch_required if {
	measure_year <= params.stall_sketch_required_until_year
	count(applied_categories) > 0
}

application_violations contains {"rule_id": "O6_21-SKETCH-001", "item": "stall_sketch", "reason": "Stallskizze bzw. Belegungsplan liegt am Betrieb nicht auf (bis Antragsjahr 2024 erforderlich)"} if {
	stall_sketch_required
	not sketch_complete
}

sketch_complete if {
	o6_21_input.stall_sketch_available == true
	o6_21_input.occupancy_plan_available == true
}

# ---------------------------------------------------------------------------
# Maßnahmenübernahme (O6_21-GEN-008)
# ---------------------------------------------------------------------------

takeover_admissible if {
	t := o6_21_input.takeover
	t.reason in data.o6_21.general_conditions.takeover_admissible_reasons
	t.animals_and_areas_from_same_predecessor == true
}

application_violations contains {"rule_id": "O6_21-GEN-008", "item": "takeover", "reason": "Maßnahmenübernahme nur bei Betriebsauflösung, -teilung oder -zusammenlegung mit Tieren und Flächen desselben Vorbetriebs"} if {
	is_object(o6_21_input.takeover)
	not takeover_admissible
}

# ---------------------------------------------------------------------------
# Meldepflichten (O6_21-NOTIF-001 / O6_21-NOTIF-005)
# ---------------------------------------------------------------------------

# O6_21-NOTIF-005: Abgänge über die Rinderdatenbank (Schlachtung, Verkauf ...) sind nicht gesondert zu melden.
no_ama_notification_needed(a) if a.exit_reason in data.o6_21.notifications.rdb_exit_reasons_without_ama_notification

# Optionaler Zuschlag Festmistkompostierung (Kapitel 6.4 Informationsblatt, Punkt 2.21 SRL).
package oepul.o6_21

import rego.v1

comp_cfg := data.o6_21.composting

composting := object.get(o6_21_input, "composting", {})

windrows := object.get(composting, "windrows", [])

device_cfg(id) := d if {
	some d in comp_cfg.turning_devices
	d.id == id
}

method_cfg(id) := m if {
	some m in comp_cfg.windrow_methods
	m.id == id
}

turning_dates_ns(w) := sort([date_ns(d) | some d in object.get(w, "turning_dates", [])])

# O6_21-COMP-002: mindestens zweimaliges Umsetzen in einem Abstand von mindestens 14 Tagen.
turnings_sufficient(w) if {
	ds := turning_dates_ns(w)
	count(ds) >= comp_cfg.min_turnings
	some i, j
	ds[i]
	ds[j]
	i < j
	(ds[j] - ds[i]) / day_ns >= comp_cfg.min_interval_days_between_turnings
}

# O6_21-COMP-004 / O6_21-COMP-005: Kompostwender oder gleichwertiges Gerät, kein Frontlader.
turning_device_ok(w) if {
	d := device_cfg(w.turning_device)
	d.accepted == true
	not d.requires_full_turnover_proof
}

turning_device_ok(w) if {
	d := device_cfg(w.turning_device)
	d.accepted == true
	d.requires_full_turnover_proof
	w.full_turnover_ensured == true
}

# O6_21-COMP-003: Kompostwender am Betrieb oder überbetrieblicher Einsatz belegt.
device_availability_ok(w) if w.device_on_farm == true

device_availability_ok(w) if w.external_use_documented == true

has_plant_material(w) if {
	some m in object.get(w, "plant_materials", [])
	some cfg in comp_cfg.mixed_windrow_plant_materials
	cfg.id == m
}

composting_violations contains {"rule_id": "O6_21-COMP-001", "reason": "nicht der gesamte am Betrieb anfallende Festmist wird am Betrieb zu Kompostmieten aufgesetzt"} if {
	composting_supplement_applied
	not composting.all_solid_manure_in_windrows_on_farm == true
}

composting_violations contains {"rule_id": "O6_21-COMP-001", "reason": "keine Kompostmiete erfasst"} if {
	composting_supplement_applied
	count(windrows) == 0
}

composting_violations contains {"rule_id": "O6_21-COMP-002", "windrow_id": w.windrow_id, "reason": "weniger als zwei Umsetzvorgänge im Abstand von mindestens 14 Tagen"} if {
	composting_supplement_applied
	some w in windrows
	w.method == "turned"
	not turnings_sufficient(w)
}

composting_violations contains {"rule_id": rid, "windrow_id": w.windrow_id, "reason": "Umsetzgerät nicht zulässig oder vollständige Umsetzung nicht gewährleistet"} if {
	composting_supplement_applied
	some w in windrows
	w.method == "turned"
	not turning_device_ok(w)
	rid := device_rule(w)
}

device_rule(w) := "O6_21-COMP-004" if w.turning_device == "front_loader"

else := "O6_21-COMP-005"

composting_violations contains {"rule_id": "O6_21-COMP-003", "windrow_id": w.windrow_id, "reason": "Umsetzgerät weder am Betrieb vorhanden noch überbetriebliche Verwendung belegt"} if {
	composting_supplement_applied
	some w in windrows
	w.method == "turned"
	not device_availability_ok(w)
}

# O6_21-COMP-006: gemischte/geschichtete Mieten erst ab Antragsjahr 2025 anerkannt.
composting_violations contains {"rule_id": "O6_21-COMP-006", "windrow_id": w.windrow_id, "reason": "Misch-/Schichtmiete ohne Umsetzen vor dem Antragsjahr 2025 bzw. ohne Material der Feldproduktion/Strauch- oder Astmaterial"} if {
	composting_supplement_applied
	some w in windrows
	w.method == "mixed_layered"
	not mixed_windrow_ok(w)
}

mixed_windrow_ok(w) if {
	measure_year >= method_cfg("mixed_layered").from_year
	has_plant_material(w)
}

# O6_21-COMP-007 / O6_21-COMP-008: wendefreie Kompostierung nur mit Beimengung und Kompostierungsverfahren.
composting_violations contains {"rule_id": "O6_21-COMP-007", "windrow_id": w.windrow_id, "reason": "wendefreie Miete ohne nennenswerte Beimengung organischen Materials oder ohne Kompostierungsverfahren"} if {
	composting_supplement_applied
	some w in windrows
	w.method == "turn_free_with_admixture"
	not turn_free_ok(w)
}

turn_free_ok(w) if {
	w.organic_material_admixture_substantial == true
	w.composting_process_applied == true
	not w.straw_rich_manure_only == true
}

composting_violations contains {"rule_id": "O6_21-COMP-008", "windrow_id": w.windrow_id, "reason": "strohreicher Mist allein erfüllt nicht die Voraussetzungen der wendefreien Kompostierung"} if {
	composting_supplement_applied
	some w in windrows
	w.method == "turn_free_with_admixture"
	w.straw_rich_manure_only == true
}

composting_violations contains {"rule_id": "O6_21-COMP-001", "windrow_id": w.windrow_id, "reason": "unbekannte Kompostierungsmethode"} if {
	composting_supplement_applied
	some w in windrows
	not method_cfg(w.method)
}

# O6_21-COMP-009: Dokumentation der Anlage, des Umsetzens und des Ausbringens bzw. der Abgabe.
composting_violations contains {"rule_id": "O6_21-COMP-009", "reason": "Dokumentation der Kompostierung unvollständig"} if {
	composting_supplement_applied
	some item in comp_cfg.documentation_items
	not item in {i | some i in object.get(composting, "documented_items", [])}
}

# O6_21-COMP-011: Vorgaben der Nitrat-Aktionsprogramm-Verordnung bei der Anlage von Kompostmieten.
composting_violations contains {"rule_id": "O6_21-COMP-011", "reason": "Vorgaben der Nitrat-Aktionsprogramm-Verordnung nicht eingehalten"} if {
	composting_supplement_applied
	composting.napv_compliant == false
}

# O6_21-COMP-012: kein Zuschlag für Kompostställe.
composting_violations contains {"rule_id": "O6_21-COMP-012", "reason": "Kompoststall - Zuschlag nicht gewährbar"} if {
	composting_supplement_applied
	composting.compost_barn == true
}

default composting_supplement_eligible := false

composting_supplement_eligible if {
	composting_supplement_applied
	count(composting_violations) == 0
}

# Allgemeine Teilnahmebedingungen und Allgemeiner Teil der SRL, soweit für o6_21 maßgeblich.
package oepul.o6_21

import rego.v1

gen := data.o6_21.general_conditions

applicant := object.get(input, ["farm", "applicant"], {})

applicant_type_cfg(t) := cfg if {
	some cfg in gen.applicant_types
	cfg.id == t
}

# O6_21-GEN-001: förderwerbende Personen; Gebietskörperschaften (und Beteiligung > 25 %) ausgeschlossen,
# o6_21 ist keine Ausnahmemaßnahme.
general_violations contains {"rule_id": "O6_21-GEN-001", "reason": "keine zulässige förderwerbende Person"} if {
	not applicant_type_cfg(applicant.type).eligible == true
}

general_violations contains {"rule_id": "O6_21-GEN-001", "reason": "Beteiligung von Gebietskörperschaften über 25 %"} if {
	applicant_type_cfg(applicant.type).public_share_limit_applies == true
	applicant.public_body_share_percent > gen.public_body_max_share_percent
}

# O6_21-GEN-002: aktiver Landwirt und landwirtschaftliche Tätigkeit.
general_violations contains {"rule_id": "O6_21-GEN-002", "reason": "kein aktiver Landwirt bzw. keine landwirtschaftliche Tätigkeit"} if {
	not applicant.is_active_farmer == true
}

general_violations contains {"rule_id": "O6_21-GEN-002", "reason": "kein aktiver Landwirt bzw. keine landwirtschaftliche Tätigkeit"} if {
	not applicant.agricultural_activity == true
}

# O6_21-GEN-004: Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr.
first_oepul_year if input.farm.oepul_first_participation_year == measure_year

farm_minimum_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= gen.farm_minimum_size_first_year.protected_cultivation_min_ha
}

farm_minimum_size_met if {
	input.land.total_area_ha >= gen.farm_minimum_size_first_year.agricultural_area_min_ha
}

general_violations contains {"rule_id": "O6_21-GEN-004", "reason": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr nicht erreicht"} if {
	first_oepul_year
	not farm_minimum_size_met
}

# O6_21-GEN-012: Verweigerung der Kontrolle - Antrag abgelehnt, Verträge beendet.
inspection_refused if {
	input.oepul.controls.inspection_refused == true
	not input.oepul.controls.force_majeure_or_exceptional == true
}

general_violations contains {"rule_id": "O6_21-GEN-012", "reason": "Vor-Ort-Kontrolle verhindert bzw. Auskunft verweigert"} if {
	inspection_refused
}

# O6_21-GEN-010: Betriebsgrößenmodulation nach Gesamtfläche des Betriebes.
bracket_upper(b, area) := area if b.to_ha_inclusive == null

bracket_upper(b, area) := min([area, b.to_ha_inclusive]) if is_number(b.to_ha_inclusive)

bracket_weighted(b, area) := max([0, bracket_upper(b, area) - b.from_ha_exclusive]) * b.payout_share

modulation_factor(area) := 1 if area <= 0

modulation_factor(area) := f if {
	area > 0
	f := sum([bracket_weighted(b, area) | some b in gen.modulation_brackets]) / area
}

# O6_21-GEN-015: Sanktionsstufen; ab 2027 Einbehalt von 1 % statt Verwarnung.
sanction_reduction_percent(stage_id, year) := s.from_2027_retention_percent if {
	some s in gen.sanction_stages
	s.id == stage_id
	stage_id == "warning"
	year >= gen.warning_replaced_by_retention_from_year
} else := s.reduction_percent if {
	some s in gen.sanction_stages
	s.id == stage_id
}

# O6_21-GEN-015: Ausschluss bei zweimaliger 100 %-Kürzung im Vertragszeitraum.
exclusion_from_measure(reductions_100_in_contract_period) if reductions_100_in_contract_period >= 2

# O6_21-GEN-011: Auszahlung bis 30. Juni des Folgejahres, Teilzahlung max. 75 %, Bagatellgrenze 50 Euro.
payment_deadline := sprintf("%d-%s", [measure_year + 1, params.payment_deadline_month_day_following_year])

max_advance_payment(amount) := amount * params.max_advance_payment_share

payout_may_be_withheld(amount) if amount <= params.minimum_payout_eur

# O6_21-GEN-020: tierhaltender Betrieb (mind. 0,30 RGVE/ha Futterfläche) - für o6_21 nicht prämienbestimmend.
livestock_holding_farm(total_rgve, forage_area_ha) if {
	forage_area_ha > 0
	total_rgve / forage_area_ha >= gen.livestock_holding_farm_min_rgve_per_ha_forage
}

# Stallhaltung: Stalldefinition, Liegebereich, Einstreu, Platzangebot, Gruppenhaltung (Kapitel 5, 6.3 Informationsblatt).
package oepul.o6_21

import rego.v1

epsilon := 0.000001

# ---------------------------------------------------------------------------
# Stalldefinition (O6_21-DEF-001 bis O6_21-DEF-004)
# ---------------------------------------------------------------------------

stall_violations contains {"rule_id": "O6_21-DEF-001", "stall_id": b.stall_id, "reason": "Stall ohne mindestens dreiseitige Verschalung bzw. dreiseitigen Behang mit Windfangnetzen"} if {
	some b in stall_buildings
	b.system == "closed"
	not b.three_sided_enclosure == true
}

stall_violations contains {"rule_id": "O6_21-DEF-001", "stall_id": b.stall_id, "reason": "Liegeplätze nicht überdacht"} if {
	some b in stall_buildings
	b.system == "closed"
	not b.roof_over_lying_places == true
}

stall_violations contains {"rule_id": "O6_21-DEF-001", "stall_id": b.stall_id, "reason": "kein befestigter Boden (Schotter oder Lehm gelten nicht als befestigt)"} if {
	some b in stall_buildings
	b.system == "closed"
	not closed_stall_floor_fixed(b)
}

closed_stall_floor_fixed(b) if {
	b.floor_fixed == true
	not b.floor_material in space.unfixed_floor_materials
}

stall_violations contains {"rule_id": "O6_21-DEF-002", "stall_id": b.stall_id, "reason": "anfallender flüssiger Kot und Harn kann nicht in einem Behälter gesammelt werden"} if {
	some b in stall_buildings
	b.liquid_manure_occurs == true
	not b.liquid_manure_container == true
}

stall_violations contains {"rule_id": "O6_21-DEF-003", "stall_id": b.stall_id, "reason": "Offenstall ohne festes Dach über den Liegeflächen"} if {
	some b in stall_buildings
	b.system == "open"
	not b.solid_roof_over_lying_area == true
}

stall_violations contains {"rule_id": "O6_21-DEF-003", "stall_id": b.stall_id, "reason": "Offenstall-Stallflächen nicht flüssigkeitsdicht befestigt"} if {
	some b in stall_buildings
	b.system == "open"
	not b.liquid_tight_floor == true
}

stall_violations contains {"rule_id": "O6_21-DEF-003", "stall_id": b.stall_id, "reason": "Offenstall ohne gewährleisteten Abfluss der Sickerwässer in eine Sammelgrube"} if {
	some b in stall_buildings
	b.system == "open"
	not b.seepage_drain_to_collection_pit == true
}

stall_violations contains {"rule_id": "O6_21-DEF-004", "stall_id": b.stall_id, "reason": "Stall bietet nicht für alle Tiere (auch während Weideperiode abwesende) Platz"} if {
	some b in stall_buildings
	b.capacity_for_all_animals == false
}

# O6_21-COMB-003: grundsätzlich muss am Heimbetrieb ein Stall zur Verfügung stehen.
farm_violations contains {"rule_id": "O6_21-COMB-003", "reason": "kein Stall am Heimbetrieb erfasst"} if {
	count(applied_categories) > 0
	count(stall_buildings) == 0
}

# ---------------------------------------------------------------------------
# Platzangebot und Liegefläche je Stallabteil (O6_21-HOUS-006 bis O6_21-HOUS-019)
# ---------------------------------------------------------------------------

weight_fits(row, w) if {
	w > row.min_weight_kg_exclusive
	row.max_weight_kg == null
}

weight_fits(row, w) if {
	w > row.min_weight_kg_exclusive
	is_number(row.max_weight_kg)
	w <= row.max_weight_kg
}

# O6_21-HOUS-013: Mindestplatzbedarf je Tier nach Gewichtsklasse.
space_row(w) := row if {
	some row in space.young_cattle_by_weight
	weight_fits(row, w)
}

# O6_21-HOUS-013 / O6_21-HOUS-014 / O6_21-HOUS-015: geforderte nutzbare Gesamtfläche je Belegungsgruppe.
occupant_required_total_area(o) := o.count * space.cows_in_shared_group.total_area_m2_per_animal if o.kind == "cow"

occupant_required_total_area(o) := o.count * space_row(o.weight_kg).total_area_m2_per_animal if o.kind == "young_cattle"

pen_required_total_area(p) := sum([occupant_required_total_area(o) | some o in object.get(p, "occupants", [])])

# O6_21-HOUS-007 / O6_21-HOUS-016: mind. 40 % der geforderten Gesamtfläche eingestreute Liegefläche.
pen_required_bedded_area(p) := pen_required_total_area(p) * space.bedded_lying_area_min_share_of_required_total_area

# O6_21-SKETCH-003: maximal mögliche Belegung eines Stallabteils nach Gewichtsklasse.
max_animals_for_area(area_m2, weight_kg) := floor((area_m2 + epsilon) / space_row(weight_kg).total_area_m2_per_animal)

# O6_21-HOUS-017: Mutterkuhbetrieb mit Liegeboxenlaufstall - Gesamtfläche gilt bei Erfüllung des Tierschutzgesetzes als eingehalten.
cubicle_exception(p) if {
	p.cubicle_loose_housing == true
	input.farm.suckler_cow_farm == true
}

total_area_ok(p) if {
	cubicle_exception(p)
	p.tschg_minimum_met == true
}

total_area_ok(p) if {
	not cubicle_exception(p)
	p.usable_total_area_m2 + epsilon >= pen_required_total_area(p)
}

# O6_21-HOUS-018: Liegefläche gilt als erreicht, wenn jedes Tier > 6 Monate eine Liegebox hat
# und alle Kälber einen zusätzlichen, ständig erreichbaren Liegeplatz haben.
lying_area_ok(p) if {
	cubicle_exception(p)
	p.all_animals_over_6_months_have_cubicle == true
	p.calves_have_additional_lying_place == true
}

lying_area_ok(p) if {
	not cubicle_exception(p)
	p.bedded_lying_area_m2 + epsilon >= pen_required_bedded_area(p)
}

pen_violations contains {"rule_id": "O6_21-HOUS-013", "pen_id": p.pen_id, "reason": "nutzbare Gesamtfläche unter Mindestplatzbedarf"} if {
	some p in pens
	not total_area_ok(p)
}

pen_violations contains {"rule_id": "O6_21-HOUS-007", "pen_id": p.pen_id, "reason": "eingestreute Liegefläche unter 40 % der geforderten nutzbaren Gesamtfläche"} if {
	some p in pens
	not lying_area_ok(p)
}

# O6_21-HOUS-019: im Kälberschlupf mind. 40 % der geforderten Gesamtfläche eingestreut.
pen_violations contains {"rule_id": "O6_21-HOUS-019", "pen_id": p.pen_id, "reason": "eingestreute Liegefläche im Kälberschlupf unter 40 %"} if {
	some p in pens
	cubicle_exception(p)
	creep := p.calf_creep
	required := pen_required_total_area(creep) * space.bedded_lying_area_min_share_of_required_total_area
	creep.bedded_lying_area_m2 + epsilon < required
}

# O6_21-HOUS-006: geschlossene (planbefestigte) Liegefläche, max. 5 % Perforation.
pen_violations contains {"rule_id": "O6_21-HOUS-006", "pen_id": p.pen_id, "reason": "Liegefläche nicht planbefestigt (Perforationsanteil über 5 %)"} if {
	some p in pens
	p.lying_area_perforation_percent > space.closed_lying_area_max_perforation_percent
}

# O6_21-HOUS-010: harter Gummi oder befestigte Fläche - mind. 3 cm Einstreudecke.
pen_violations contains {"rule_id": "O6_21-HOUS-010", "pen_id": p.pen_id, "reason": "Einstreudecke unter 3 cm auf hartem Gummi bzw. befestigter Liegefläche"} if {
	some p in pens
	some t in space.lying_surface_types
	t.id == p.lying_surface
	is_number(t.min_litter_depth_cm)
	p.litter_depth_cm < t.min_litter_depth_cm
}

# O6_21-HOUS-009: weicher Kunststoff/Gummi - Einstreu zur Sicherstellung der Trockenheit.
pen_violations contains {"rule_id": "O6_21-HOUS-009", "pen_id": p.pen_id, "reason": "weiche Liegefläche ohne Einstreu zur Sicherstellung der Trockenheit"} if {
	some p in pens
	p.lying_surface == "soft_plastic_or_rubber"
	not p.littered == true
}

# O6_21-HOUS-008 / O6_21-HOUS-011: ausreichend saugfähige, weiche Einstreu - weiche und trockene Liegefläche.
pen_violations contains {"rule_id": "O6_21-HOUS-008", "pen_id": p.pen_id, "reason": "keine weiche und trockene Liegefläche gewährleistet"} if {
	some p in pens
	p.lying_area_soft_and_dry == false
}

pen_violations contains {"rule_id": "O6_21-HOUS-011", "pen_id": p.pen_id, "reason": "Einstreu nicht saugfähig und weich"} if {
	some p in pens
	p.litter_absorbent_and_soft == false
}

# O6_21-DEF-006: Absperren von Teilflächen nur für Routinearbeiten zulässig.
pen_violations contains {"rule_id": "O6_21-DEF-006", "pen_id": p.pen_id, "reason": "Teilflächen außerhalb von Routinearbeiten abgesperrt"} if {
	some p in pens
	p.subareas_closed_off_outside_routine_work == true
}

# O6_21-DEF-005: nutzbare Gesamtfläche nur befestigte Flächen mit ständigem Zugang.
pen_violations contains {"rule_id": "O6_21-DEF-005", "pen_id": p.pen_id, "reason": "angerechnete Fläche nicht befestigt oder nicht ständig zugänglich"} if {
	some p in pens
	p.counted_area_fixed_and_permanently_accessible == false
}

# ---------------------------------------------------------------------------
# Tierbezogene Haltungsverstöße (O6_21-HOUS-001, O6_21-SINGLE-*, O6_21-COMB-002)
# ---------------------------------------------------------------------------

housing(a) := object.get(a, "housing", {})

single_housing(a) := object.get(housing(a), "single_housing", null)

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": "O6_21-HOUS-001", "reason": "keine Gruppenhaltung"} if {
	some a in cattle
	housing(a).group_housed == false
}

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": "O6_21-HOUS-001", "reason": "kein eingestreutes System"} if {
	some a in cattle
	housing(a).bedded_system == false
}

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": "O6_21-HOUS-001", "reason": "Anbindehaltung"} if {
	some a in cattle
	housing(a).tethered == true
}

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": "O6_21-HOUS-001", "reason": "Haltung auf Vollspaltensystem"} if {
	some a in cattle
	housing(a).full_slatted == true
}

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": "O6_21-COMB-002", "reason": "ganzjährige Freilandhaltung ohne entsprechendes Stallsystem"} if {
	some a in cattle
	housing(a).year_round_outdoor_without_stall == true
}

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": v.rule_id, "reason": sprintf("Stallabteil %s: %s", [p.pen_id, v.reason])} if {
	some a in cattle
	p := pens_by_id[housing(a).pen_id]
	some v in pen_violations
	v.pen_id == p.pen_id
}

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": v.rule_id, "reason": sprintf("Stall %s: %s", [v.stall_id, v.reason])} if {
	some a in cattle
	p := pens_by_id[housing(a).pen_id]
	some v in stall_violations
	v.stall_id == p.stall_id
}

# O6_21-SINGLE-006: Kälber unter 21 Tagen dürfen einzeln auf eingestreutem System mit Sozialkontakt gehalten werden.
calf_single_housing_ok(sh) if {
	sh.calf_age_days_at_end < params.calf_single_housing_max_age_days_exclusive
	sh.bedded == true
	sh.social_contact == true
}

# O6_21-SINGLE-001 / O6_21-SINGLE-002: Einzelhaltung kranker/verletzter Tiere max. 10 Tage auf eingestreutem System.
sick_single_housing_ok(sh) if {
	sh.reason in {"illness", "injury"}
	sh.days <= params.single_housing_max_days
	sh.bedded == true
}

animal_breaches contains {"ear_tag": a.ear_tag, "rule_id": rid, "reason": reason} if {
	some a in cattle
	sh := single_housing(a)
	is_object(sh)
	not calf_single_housing_ok(sh)
	not sick_single_housing_ok(sh)
	[rid, reason] := single_housing_breach(sh)
}

single_housing_breach(sh) := ["O6_21-SINGLE-003", "Einzeltierhaltung länger als 10 Tage"] if {
	sh.reason in {"illness", "injury"}
	sh.days > params.single_housing_max_days
} else := ["O6_21-SINGLE-002", "Einzeltierhaltung nicht auf eingestreutem System"] if {
	sh.reason in {"illness", "injury"}
	not sh.bedded == true
} else := ["O6_21-SINGLE-001", "Einzeltierhaltung ohne gesundheitlichen Grund bzw. ohne zulässige Kälberausnahme"]

# O6_21-SINGLE-004: Dokumentation von Krankheit/Verletzung und Dauer (Aufzeichnungsverstoß, kein Abmeldegrund).
documentation_violations contains {"rule_id": "O6_21-SINGLE-004", "ear_tag": a.ear_tag, "reason": "Einzeltierhaltung nicht dokumentiert"} if {
	some a in cattle
	sh := single_housing(a)
	is_object(sh)
	sh.reason in {"illness", "injury"}
	not sh.documented == true
}

# Beginn des Verstoßes; ohne Angabe wird der Verstoß ab Jahresbeginn angenommen.
breach_start_ns(a) := date_ns(housing(a).conditions_breached_from) if {
	is_string(housing(a).conditions_breached_from)
} else := year_start_ns

# O6_21-NOTIF-004: ein Verstoß ist nur relevant, wenn er in ein Verpflichtungsfenster einer beantragten Kategorie fällt.
breach_relevant(a) if {
	some b in animal_breaches
	b.ear_tag == a.ear_tag
	some c in applied_categories
	w := obligation_window(a, categories_by_id[c])
	breach_start_ns(a) < w[1]
}

# O6_21-NOTIF-001 / O6_21-SINGLE-003: Tiere, die abgemeldet werden müssen.
deregistration_required contains a.ear_tag if {
	some a in cattle
	breach_relevant(a)
}

deregistered(a) if a.o6_21_deregistered == true

# O6_21-NOTIF-001: nicht gemeldete Nichteinhaltung ist ein Verstoß gegen die Meldepflicht.
unreported_noncompliance contains a.ear_tag if {
	some a in cattle
	a.ear_tag in deregistration_required
	not deregistered(a)
}

